{
  "segment_function": "definition",
  "claims": [
    {
      "claim": "The vita activa is designated by three fundamental human activities: labor, work, and action.",
      "claim_type": "author_position",
      "supporting_excerpt": "With the term vita activa , I propose to designate three fundamental human activities: labor, work, and action.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "Men are conditioned beings because everything they come into contact with immediately turns into a condition of their existence.",
      "claim_type": "author_position",
      "supporting_excerpt": "Men are conditioned beings because everything they come in contact with turns immediately into a condition of their existence.",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "Labor",
      "definition": "The activity that corresponds to the biological process of the human body, whose vital necessities are bound to spontaneous growth, metabolism, and decay."
    },
    {
      "term": "Work",
      "definition": "The activity that corresponds to the unnaturalness of human existence, providing an artificial world of things meant to outlast and transcend individual life cycles."
    },
    {
      "term": "Action",
      "definition": "The only activity that goes on directly between men without the intermediary of things or matter, corresponding to the human condition of plurality."
    }
  ],
  "distinctions": [
    {
      "item_a": "Labor",
      "item_b": "Work",
      "distinction": "Labor corresponds to the biological process and life itself, whereas work corresponds to worldliness and provides an artificial world of things distinct from natural surroundings."
    }
  ],
  "examples": [],
  "objections": [],
  "responses": [],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The connection of the three fundamental activities to natality and mortality.",
    "The concept of human beings as always being conditioned beings."
  ]
}

